namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple yet delicious pizza with fresh mozzarella and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = ["Preheat oven to 475°F.", "Roll out dough on a floured surface.", "Spread crushed tomatoes evenly.", "Tear mozzarella and distribute on top.", "Bake for 10-12 minutes until crust is golden.", "Top with fresh basil and drizzle olive oil."],
            TotalRatings = 12, RatingSum = 52
        },
        new()
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken pieces in a creamy, spiced tomato sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
            Steps = ["Marinate chicken in yogurt and spices for 2 hours.", "Grill or pan-sear chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and simmer 15 minutes.", "Stir in cream and cooked chicken.", "Simmer 10 more minutes and serve with rice."],
            TotalRatings = 8, RatingSum = 38
        },
        new()
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in crispy taco shells with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
            Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 minutes.", "Warm taco shells in oven.", "Fill shells with beef.", "Top with lettuce, tomato, cheese, sour cream, and salsa."],
            TotalRatings = 15, RatingSum = 63
        },
        new()
        {
            Id = 4, Title = "Pad Thai", Category = "Asian",
            Description = "Stir-fried rice noodles with shrimp, peanuts, and tangy sauce.",
            Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Peanuts", "Lime", "Fish sauce", "Tamarind paste", "Sugar"],
            Steps = ["Soak rice noodles in warm water 30 minutes.", "Mix fish sauce, tamarind paste, and sugar for sauce.", "Stir-fry shrimp until pink, set aside.", "Scramble eggs in the wok.", "Add noodles and sauce, toss until coated.", "Add shrimp, bean sprouts, and peanuts. Serve with lime."],
            TotalRatings = 10, RatingSum = 45
        },
        new()
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich chocolate cake with a molten center.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps = ["Preheat oven to 425°F. Grease ramekins.", "Melt chocolate and butter together.", "Whisk eggs, sugar, and vanilla until thick.", "Fold chocolate mixture into eggs.", "Add flour and gently fold.", "Pour into ramekins and bake 12-14 minutes."],
            TotalRatings = 20, RatingSum = 94
        },
        new()
        {
            Id = 6, Title = "Caesar Salad", Category = "Salads",
            Description = "Crisp romaine lettuce with creamy Caesar dressing and croutons.",
            Ingredients = ["Romaine lettuce", "Parmesan cheese", "Croutons", "Caesar dressing", "Lemon juice", "Anchovy paste"],
            Steps = ["Wash and chop romaine lettuce.", "Make dressing: mix Caesar dressing, lemon juice, and anchovy paste.", "Toss lettuce with dressing.", "Top with shaved Parmesan and croutons.", "Serve immediately."],
            TotalRatings = 6, RatingSum = 25
        }
    ];

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Description = $"A community-submitted recipe for {submission.Title}.",
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        });
    }
}

@page "/"
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>RecipeHub - Recipe Sharing Community</PageTitle>

<h1>🍳 Welcome to RecipeHub</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row mt-3">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@GetCategoryEmoji(category) @category</h5>
                    <p class="card-text">@RecipeService.GetRecipesByCategory(category).Count recipe(s)</p>
                    <a href="/recipes/@category" class="btn btn-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍕",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Asian" => "🍜",
        "Desserts" => "🍫",
        "Salads" => "🥗",
        _ => "🍽️"
    };
}

@page "/recipes/{Category}"
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@Category Recipes - RecipeHub</PageTitle>

<h1>@Category Recipes</h1>
<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@Category</li>
    </ol>
</nav>

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <p class="text-muted">⭐ @recipe.AverageRating.ToString("F1") (@recipe.TotalRatings ratings)</p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>The requested recipe does not exist.</p>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/recipes/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="lead">@recipe.Description</p>

    <div class="mb-4">
        <StarRating RecipeId="recipe.Id" CurrentAverage="recipe.AverageRating" TotalRatings="recipe.TotalRatings" />
    </div>

    <h3>Ingredients</h3>
    <ul class="list-group list-group-flush mb-4">
        @foreach (var ingredient in recipe.Ingredients)
        {
            <li class="list-group-item">@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol class="list-group list-group-numbered mb-4">
        @foreach (var step in recipe.Steps)
        {
            <li class="list-group-item">@step</li>
        }
    </ol>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipeById(Id);
    }
}

@page "/submit"
@using RecipeHub.Models
@using RecipeHub.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>🎉 Recipe Submitted!</h4>
        <p>Your recipe "<strong>@submission.Title</strong>" has been added to the community.</p>
        <a href="/" class="btn btn-primary">Back to Home</a>
    </div>
}
else
{
    <EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="submission.Title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
                <option value="">Select a category...</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="submission.Ingredients"
                placeholder="2 cups flour&#10;1 cup sugar&#10;3 large apples..." />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="submission.Steps"
                placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;..." />
        </div>

        <button type="submit" class="btn btn-success" disabled="@(!IsValid)">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeSubmission submission = new();
    private bool submitted;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(submission.Title) &&
        !string.IsNullOrWhiteSpace(submission.Category) &&
        !string.IsNullOrWhiteSpace(submission.Ingredients) &&
        !string.IsNullOrWhiteSpace(submission.Steps);

    private void HandleSubmit()
    {
        if (IsValid)
        {
            RecipeService.AddRecipe(submission);
            submitted = true;
        }
    }
}

@using RecipeHub.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="d-flex align-items-center gap-2">
    <span class="star-rating">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= hoveredStar ? "hovered" : "") @(userRating > 0 && star <= userRating ? "rated" : "")"
                  @onclick="() => Rate(star)"
                  @onmouseover="() => hoveredStar = star"
                  @onmouseout="() => hoveredStar = 0"
                  role="button"
                  title="Rate @star star(s)">
                @(star <= (hoveredStar > 0 ? hoveredStar : userRating) ? "★" : "☆")
            </span>
        }
    </span>
    <span class="text-muted ms-2">
        @if (userRating > 0)
        {
            <text>You rated @userRating/5 · </text>
        }
        @CurrentAverage.ToString("F1") avg (@TotalRatings ratings)
    </span>
</div>

<style>
    .star-rating .star {
        font-size: 1.5rem;
        cursor: pointer;
        color: #ccc;
        transition: color 0.15s;
    }
    .star-rating .star.hovered,
    .star-rating .star.rated {
        color: #ffc107;
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentAverage { get; set; }
    [Parameter] public int TotalRatings { get; set; }

    private int hoveredStar;
    private int userRating;

    private void Rate(int stars)
    {
        userRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            CurrentAverage = recipe.AverageRating;
            TotalRatings = recipe.TotalRatings;
        }
    }
}

