@page "/submit"
@using RecipeHub.Models
@using RecipeHub.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>🎉 Recipe Submitted!</h4>
        <p>Your recipe "<strong>@submission.Title</strong>" has been added to the community.</p>
        <a href="/" class="btn btn-primary">Back to Home</a>
    </div>
}
else
{
    <EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="submission.Title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
                <option value="">Select a category...</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="submission.Ingredients"
                placeholder="2 cups flour&#10;1 cup sugar&#10;3 large apples..." />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="submission.Steps"
                placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;..." />
        </div>

        <button type="submit" class="btn btn-success" disabled="@(!IsValid)">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeSubmission submission = new();
    private bool submitted;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(submission.Title) &&
        !string.IsNullOrWhiteSpace(submission.Category) &&
        !string.IsNullOrWhiteSpace(submission.Ingredients) &&
        !string.IsNullOrWhiteSpace(submission.Steps);

    private void HandleSubmit()
    {
        if (IsValid)
        {
            RecipeService.AddRecipe(submission);
            submitted = true;
        }
    }
}

@using RecipeHub.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="d-flex align-items-center gap-2">
    <span class="star-rating">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= hoveredStar ? "hovered" : "") @(userRating > 0 && star <= userRating ? "rated" : "")"
                  @onclick="() => Rate(star)"
                  @onmouseover="() => hoveredStar = star"
                  @onmouseout="() => hoveredStar = 0"
                  role="button"
                  title="Rate @star star(s)">
                @(star <= (hoveredStar > 0 ? hoveredStar : userRating) ? "★" : "☆")
            </span>
        }
    </span>
    <span class="text-muted ms-2">
        @if (userRating > 0)
        {
            <text>You rated @userRating/5 · </text>
        }
        @CurrentAverage.ToString("F1") avg (@TotalRatings ratings)
    </span>
</div>

<style>
    .star-rating .star {
        font-size: 1.5rem;
        cursor: pointer;
        color: #ccc;
        transition: color 0.15s;
    }
    .star-rating .star.hovered,
    .star-rating .star.rated {
        color: #ffc107;
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentAverage { get; set; }
    [Parameter] public int TotalRatings { get; set; }

    private int hoveredStar;
    private int userRating;

    private void Rate(int stars)
    {
        userRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            CurrentAverage = recipe.AverageRating;
            TotalRatings = recipe.TotalRatings;
        }
    }
}

